<?php
/**
 * The welcome bubble is flow-owned, so it has to be able to name whoever is
 * attached right now.
 *
 * A visitor's opening message is not generated by the model. It is the flow's
 * saved IVR message, rendered by the client. So a flow whose attached
 * personality changed from Br3nda to DadJokeDan still greeted the visitor in
 * Br3nda's name, and the AI tab being perfect made no difference — the AI had
 * not spoken yet.
 *
 * The fix is a personality-agnostic greeting the floscAdmin writes once, with
 * variables resolved at render time. Which only works if three things stay
 * true together: the server exposes the values, the client substitutes them,
 * and the editor tells the floscAdmin they exist. Any one of those going
 * missing turns the greeting into "I'm {personality_name}" on a live site,
 * which is what a visitor actually saw.
 */

if ( PHP_SAPI !== 'cli' ) {
	exit;
}

$root = dirname( __DIR__ );
$fail = 0;

function ok( $label, $actual, $expected ) {
	global $fail;
	$pass = $actual === $expected;
	if ( ! $pass ) { $fail++; }
	printf( "%s %-62s %s%s\n", $pass ? 'ok  ' : 'FAIL', $label, var_export( $actual, true ), $pass ? '' : ' (want ' . var_export( $expected, true ) . ')' );
}

$boot   = (string) file_get_contents( $root . '/admin/flosc-app.php' );
$client = (string) file_get_contents( $root . '/assets/js/flosc-app.js' );
$editor = (string) file_get_contents( $root . '/admin/ivr-messages.php' );

$variables = array(
	'{personality_name}' => 'personalityName',
	'{personality_role}' => 'personalityRole',
	'{flow_name}'        => 'flowDisplayName',
	'{public_title}'     => null,
	'{tagline}'          => null,
	'{site_name}'        => 'siteName',
);

echo "Every greeting variable is substituted by the client\n";
foreach ( array_keys( $variables ) as $token ) {
	$pattern = '/\.replace\(\s*\/\{' . preg_quote( trim( $token, '{}' ), '/' ) . '\}\/g/';
	ok( $token . ' is replaced', (bool) preg_match( $pattern, $client ), true );
}

echo "\nThe server hands the client the values it substitutes\n";
foreach ( array_filter( $variables ) as $token => $config_key ) {
	ok( $config_key . " is in the boot config  ($token)",
		strpos( $boot, "'" . $config_key . "'" ) !== false, true );
}

// Resolved when the page renders, from the row attached at that moment. A
// value snapshotted onto the flow at attach time would greet as whoever was
// attached when it was saved.
echo "\nThe personality role is resolved at render time, not snapshotted\n";
ok( 'the role comes from the library resolver',
	strpos( $boot, "flosc_personality_library_resolve_field( 'ai_personality_role'" ) !== false, true );

echo "\nThe editor tells the floscAdmin these exist\n";
foreach ( array_keys( $variables ) as $token ) {
	ok( $token . ' is documented beside the content field',
		strpos( $editor, '<code>' . $token . '</code>' ) !== false, true );
}
ok( 'and so are the three line-break forms',
	strpos( $editor, 'for a visible line break' ) !== false, true );

// Typed \n, a real newline and <br> all mean the same thing to a floscAdmin
// writing a message. A visitor should never see the difference.
echo "\nAll three line-break forms render\n";
ok( 'a literal backslash-n is converted',
	strpos( $client, "replace(/\\\\n/g, '\\n')" ) !== false, true );
ok( 'so is <br>',
	strpos( $client, "replace(/<br\\s*\\/?>/gi, '\\n')" ) !== false, true );
ok( 'and the result is rendered as a break',
	strpos( $client, "replace(/\\n/g, '<br>')" ) !== false, true );

echo $fail ? "\n$fail FAILURES\n" : "\nA greeting written once can introduce whoever is attached\n";
exit( $fail ? 1 : 0 );
